#include <stdio.h>
#include <string.h>
#include <ctype.h>

static int is_leap_year(int year) {
    return (year % 4 == 0) && (year % 100 != 0 || year % 400 == 0);
}

static int days_in_month(int year, int month) {
    static const int dim[12] = {31,28,31,30,31,30,31,31,30,31,30,31};
    if (month == 2 && is_leap_year(year)) return 29;
    return dim[month-1];
}

int main(int argc, char *argv[]) {
    if (argc < 2) { puts("INVALID"); return 0; }
    const char *s = argv[1];
    if (strlen(s) != 10) { puts("INVALID"); return 0; }
    if (!isdigit((unsigned char)s[0])||!isdigit((unsigned char)s[1])||!isdigit((unsigned char)s[2])||!isdigit((unsigned char)s[3])||s[4]!='-'||!isdigit((unsigned char)s[5])||!isdigit((unsigned char)s[6])||s[7]!='-'||!isdigit((unsigned char)s[8])||!isdigit((unsigned char)s[9])) {
        puts("INVALID"); return 0; }
    int year = (s[0]-'0')*1000 + (s[1]-'0')*100 + (s[2]-'0')*10 + (s[3]-'0');
    int month = (s[5]-'0')*10 + (s[6]-'0');
    int day = (s[8]-'0')*10 + (s[9]-'0');
    if (month < 1 || month > 12) { puts("INVALID"); return 0; }
    if (day < 1 || day > days_in_month(year, month)) { puts("INVALID"); return 0; }
    puts("VALID");
    return 0;
}
